"""Linus's concept: a negotiation agent that learns from the finished cases of its own run.

Sub-agents per decision (LangGraph): Observer -> Router -> Offer Builder -> Negotiator (LLM) -> Critic,
or Closer -> Reflector (LLM) when the case ends. See agents/_learner/README.md.
"""

import sys
from pathlib import Path

_ROOT = str(Path(__file__).resolve().parents[1])
if _ROOT not in sys.path:
    sys.path.insert(0, _ROOT)


class Agent:
    def __init__(self):
        self._cache = {}

    def prepare(self, context):
        try:
            from agents._learner import core

            return core.prepare(context, self._cache)
        except Exception as e:  # a broken plugin must not cost the case: play the safe policy
            return {"v": 0, "broken": type(e).__name__, "p": dict(context.get("parameters") or {})}

    def decide(self, observation, state, services):
        try:
            from agents._learner import core

            return core.decide(observation, state, services, self._cache)
        except Exception as e:
            return emergency(observation, state, type(e).__name__)

    def on_result(self, context, state, services):
        from agents._learner.core import on_result

        return on_result(context, state, services)


def emergency(observation, state, reason):
    """Last resort: ask a question (no term sheets) while rounds last, then the harness's safe close."""
    from arena_kit.harness.validation import close_action
    from arena_kit.play import moves_left

    case, threads = observation["case"], observation["threads"]
    state = dict(state or {})
    state["emergencies"] = state.get("emergencies", 0) + 1
    state["emergency_reason"] = reason
    llm = dict(state.get("llm") or {})
    llm["fails"] = max(2, llm.get("fails", 0))  # if the model output caused this, do not call it again
    state["llm"] = llm
    ready = observation.get("ready_suppliers") or []
    if state["emergencies"] <= 3 and ready and all(moves_left(case, threads[s]) > 1 for s in ready):
        body = (
            "Dear colleagues,\nthank you for your message. Could you tell us where you see flexibility - on price, "
            "payment terms or contract length?\nBest regards\nHollerau Pumpenwerke GmbH, Purchasing"
        )
        actions = [
            {
                "supplier_id": s,
                "message": {
                    "subject": "Re: " + str(case.get("title", "Your quote"))[:150],
                    "body": body,
                    "term_sheets": [],
                },
            }
            for s in ready
        ]
        return {"actions": actions, "state": state}
    return {"actions": [close_action(case, threads)], "state": state}

"""prepare() and decide() of the learner agent: per-process caches, the graph run, state hygiene."""

import time

from arena_kit.data import DataPackage
from arena_kit.harness.config import DEFAULT_DATA

from . import dossier as dossier_mod
from . import graph, memory, params
from .budget import Budget
from .llm import Gateway
from .state import STATE_VERSION, compact

_PACKAGES = {}


def package(p):
    root = str(p.get("data_dir") or DEFAULT_DATA)
    if root not in _PACKAGES:
        _PACKAGES[root] = DataPackage(root)
    return _PACKAGES[root]


def case_cache(case, p, cache, pkg=None):
    """Everything per case that does not change between decisions; rebuilt after a worker restart, or
    when the harness's own data package (services.data, from --data) differs from the one we used."""
    pkg = pkg or package(p)
    cc = cache.get(case["case_id"])
    if cc is None or cc.get("root") != str(pkg.root):
        cc = {"root": str(pkg.root), "facts": pkg.facts, "dossier": dossier_mod.build(case, pkg)}
        cache[case["case_id"]] = cc
    return cc


def harness_package(p, services):
    """The data package the harness runs with, unless `data_dir` pins one explicitly."""
    data = getattr(services, "data", None) if services is not None else None
    if p.get("data_dir") or not isinstance(data, DataPackage):
        return None
    return data


def initial_state(case, p, cc):
    return {
        "v": STATE_VERSION,
        "case_id": case["case_id"],
        "p": p,
        "sup": {sid: {"tags": d.get("tags", [])} for sid, d in cc["dossier"]["suppliers"].items()},
        "llm": {"fails": 0, "calls": 0},
        "log": [],
    }


def prepare(context, cache):
    case = context["case"]
    p = params.load(context.get("parameters"))
    p.update(
        {k: v for k, v in context.get("runtime", {}).items() if k in ("data_dir", "decision_seconds", "model_timeout")}
    )
    started = time.monotonic()
    cc = case_cache(case, p, cache)
    state = initial_state(case, p, cc)
    mem = memory.refresh(case, p, {s: v["tags"] for s, v in state["sup"].items()}, cc)
    state["mem"] = {
        "run": mem.get("run"),
        "episodes": mem.get("episodes", 0),
        "lessons": [x["key"] for x in mem.get("lessons", [])],
    }
    state["prepare_s"] = round(time.monotonic() - started, 3)
    return compact(state)


def decide(observation, state, services, cache):
    case = observation["case"]
    if not state or state.get("v") != STATE_VERSION or state.get("case_id") != case["case_id"]:
        p = params.load((state or {}).get("p"))
        cc = case_cache(case, p, cache)
        state = initial_state(case, p, cc)
    p = state.get("p") or params.load({})
    p = {
        **p,
        **{
            k: v
            for k, v in observation.get("runtime", {}).items()
            if k in ("data_dir", "decision_seconds", "model_timeout")
        },
    }
    cc = case_cache(case, p, cache, harness_package(p, services))
    for sid, d in cc["dossier"]["suppliers"].items():  # tags from the package actually in use
        state["sup"].setdefault(sid, {})["tags"] = d.get("tags", [])
    budget = Budget(observation, p)
    gw = Gateway(services)
    ctx = {
        "obs": observation,
        "case": case,
        "threads": observation["threads"],
        "ready": list(observation.get("ready_suppliers") or []),
        "state": state,
        "services": services,
        "p": p,
        "cc": cc,
        "budget": budget,
        "gw": gw,
    }
    out, runner = graph.run(ctx)
    state = out["state"]
    state["llm"]["calls"] = state["llm"].get("calls", 0) + gw.calls
    state["runner"] = runner
    return {"actions": out["actions"], "state": compact(state)}


def on_result(context, state, services):
    """Called only after the engine persisted a confirmed result; never delays acceptance."""
    result = context.get("result") or {}
    if not result.get("ended", "score" in result):
        return state
    state["closed"] = True
    state["reflection"] = {"source": "det", "lessons": [], "feedback": {}}
    # Deterministic diagnostics consume the actual result through history. Optional model reflection
    # is advisory and never gets causal credit from the score or changes knobs without evidence.
    p = state.get("p") or {}
    if p.get("llm") and p.get("memory", True) and services is not None:
        raw = Gateway(services).json(
            graph.prompts.reflector(
                {
                    "case": {"type": context["case"].get("type"), "negotiable": context["case"]["negotiable"]},
                    "outcome": result,
                    "decisions": state.get("log", [])[-12:],
                    "suppliers": {
                        sid: {"preferences": s.get("preferences"), "tags": s.get("tags")}
                        for sid, s in state.get("sup", {}).items()
                    },
                }
            )
        )
        if isinstance(raw, dict):
            state["reflection"] = {"source": "llm", "lessons": graph.prompts.clean_lessons(raw), "feedback": {}}
    return compact(state)
"""Agent parameters from the TOML `[parameters]` table, with safe defaults."""

DEFAULTS = {
    "llm": True,  # use the model when the budget allows; False = fully deterministic
    "two_call": True,  # allow strategist + writer when there is time for two calls
    "decision_seconds": 30,  # direct-call default; harness runtime is authoritative
    "model_timeout": 14,  # direct-call default; harness runtime is authoritative
    "data_dir": None,  # default: the repo's data/
    "memory": True,  # learn from finished cases of this run
    "max_lessons": 10,
    "anchor_drop": 0.10,  # first ask: this far below the standing value (before priors and lessons)
}


def load(parameters):
    p = dict(DEFAULTS)
    for key, value in (parameters or {}).items():
        if key in DEFAULTS:
            p[key] = value
    p["decision_seconds"] = max(1.0, min(45.0, float(p["decision_seconds"])))
    p["model_timeout"] = max(1.0, min(35.0, float(p["model_timeout"])))
    p["anchor_drop"] = max(0.0, min(0.4, float(p["anchor_drop"])))
    return p
"""Router, Closer and the deterministic policy. Closing is never left to the model."""

import math

from .claims import MAX_PER_MESSAGE

WARM = {"relationship", "cash_short", "full_order_book", "not_strategic", "unpaid"}
FIRM = {"spare_capacity", "weak_costing"}


def alternative_cost(case, services_cost):
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind") in (None, "none") or not (alt.get("terms") or {}).get("unit_price"):
        return None
    try:
        c = services_cost(case, alt["terms"])
        return c if math.isfinite(c) else None
    except Exception:
        return None


def _close(kind, sid, offer_id=None, reason=""):
    action = {"type": "accept", "term_sheet_id": offer_id} if kind == "accept" else {"type": "walk_away"}
    return {"type": "close", "supplier_id": sid, "action": action, "reason": reason}


def best_acceptable(ledgers):
    acc = [(led["c"], sid) for sid, led in ledgers.items() if led.get("acceptable") and led.get("c") is not None]
    return min(acc) if acc else None


def _may_beat(rival, c):
    """An open rival can still undercut an agreement: it is cheaper already, or still moving."""
    return rival.get("c") is None or c is None or rival["c"] < c or (rival.get("move_pct") or 0) > 0


def route(case, ledgers, ready, c_alt, knobs, last_round):
    """Close now (accept/walk) or negotiate with the ready suppliers; `final_push` marks trade-only pushes."""
    live = [s for s, led in ledgers.items() if not led.get("ended")]
    # Only a ready supplier can receive our closing action. If a busy one has a better offer, the
    # engine sees our close while that request is in flight and itself accepts the cheapest acceptable
    # offer once the reply has settled (engine.py: close with pending -> close_action).
    best = best_acceptable({s: ledgers[s] for s in ready if s in live})
    fallback_exists = c_alt is not None

    def accept_best(reason):
        if best:
            sid = best[1]
            return _close("accept", sid, ledgers[sid]["offer_id"], reason)
        return _close("walk", ready[0], reason=reason + " (nothing acceptable)")

    if last_round:
        return accept_best("wave time")
    for sid in ready:
        if ledgers[sid]["moves_left"] <= 0:
            return accept_best("no moves left")
    pushes, holds = {}, {}

    def open_rivals(sid):
        return [
            s
            for s in live
            if s != sid and ledgers[s]["status"] not in ("final_offer", "agreed") and ledgers[s]["moves_left"] >= 1
        ]

    # The cheapest acceptable final offer is our fallback when there is no alternative: never push it.
    finals = sorted(
        (ledgers[s]["c"], s)
        for s in live
        if ledgers[s]["status"] == "final_offer" and ledgers[s].get("acceptable") and ledgers[s]["c"] is not None
    )
    protected = finals[0][1] if finals else None
    for sid in sorted(ready, key=lambda s: s == protected):  # the protected fallback is decided last
        led = ledgers[sid]
        if led["status"] == "agreed" and led.get("acceptable"):
            # An agreement is our fallback while a rival can still beat it.
            if led["moves_left"] >= 2 and [s for s in open_rivals(sid) if _may_beat(ledgers[s], led["c"])]:
                holds[sid] = True
                continue
            return accept_best("agreed")
        if led["status"] != "final_offer":
            continue
        others_open = open_rivals(sid)
        pushable = knobs.get("allow_final_push", True) and led["pushes_after_final"] == 0 and led["moves_left"] >= 2
        # push only when its walking costs us nothing: our alternative is at least as good, or a cheaper
        # final offer stays as fallback. Open rivals are no such guarantee, and no deal scores 0 when the
        # alternative is no better than the opening.
        alt_as_good = fallback_exists and led["c"] is not None and c_alt <= led["c"]
        safe = alt_as_good or (protected not in (None, sid) and not pushes)
        if pushable and safe:
            pushes[sid] = True
            continue
        if (others_open or pushes) and led["moves_left"] >= 2:
            holds[sid] = True  # its final offer stands as our fallback while the others negotiate
            continue
        if led.get("acceptable"):
            return accept_best("final offer")
        if fallback_exists and not [s for s in live if s != sid]:
            return _close("walk", sid, reason="final offer worse than our alternative")
    return {"type": "negotiate", "suppliers": list(ready), "final_push": pushes, "hold": holds}


def tone_for(tags, lessons_tone=None):
    if lessons_tone:
        return lessons_tone
    if set(tags) & WARM:
        return "warm"
    if set(tags) & FIRM:
        return "firm"
    return "neutral"


def det_choose(sid, led, menu, claims, tags, final_push, first, knobs):
    """The deterministic move: same menu and claims the model would see, a fixed schedule."""
    level = "trade" if final_push else "step"
    sheets = [m for m in menu if m["level"] == level] or [m for m in menu if m["level"] == "hold"] or menu
    sheets = sheets[:2]
    n_claims = 2 if first else 1
    chosen = [c for c in claims if not c.get("reveals")][:n_claims] or claims[:n_claims]
    ask = first or (
        not led.get("breakdown") and led.get("rounds", 0) <= 1 and bool(set(tags) & {"open_books", "weak_costing"})
    )
    tactic = "trade" if final_push else ("anchor" if first else "concede")
    return {
        "tactic": tactic,
        "sheet_ids": [m["mid"] for m in sheets],
        "claim_ids": [c["cid"] for c in chosen][:MAX_PER_MESSAGE],
        "ask_breakdown": ask,
        "tone": tone_for(tags, knobs.get("tone", {}).get(sid)),
        "questions": [],
        "prediction": {"status": "open", "price_move_pct": None, "note": "deterministic"},
        "read": "",
    }

"""Offer Builder: valid term sheets of equal value to the supplier, cheapest for us first.

For every combination of the non-price levers the price is solved so that the package is worth a
target amount to the supplier (`cost.supplier_value`: a cash-short supplier values early payment).
The target walks from our aspiration towards the supplier's standing offer along a concession
schedule; `trade` packages are worth exactly as much to it as its own offer but cost us less.
"""

import itertools
import math

from arena_kit.cost import RELATIONSHIP_GOALS, must_haves_ok, supplier_value
from arena_kit.harness.valuation import effort, value

from . import priors

MAX_COMBOS = 300
PER_LEVEL = 8


def lever_domains(case, std):
    """{field: [allowed values]} for the non-price negotiable fields, or None if one has none."""
    out = {}
    for field in case["negotiable"]:
        if field == "unit_price":
            continue
        values = list(case.get("term_options", {}).get(field) or [])
        if field in std and std[field] not in values:
            values.append(std[field])
        if not values:
            return None
        out[field] = values
    return out


def _prune(domains, base):
    """Keep the product small: shrink the longest field to a spread (its ends, middle and the supplier's
    own value) until the product fits."""
    cap = 4
    orig = {f: list(v) for f, v in domains.items()}
    while math.prod(len(v) for v in domains.values()) > MAX_COMBOS and cap >= 1:
        field = max(domains, key=lambda f: len(domains[f]))
        if len(domains[field]) <= cap:
            cap -= 1
            continue
        values = orig[field]  # always spread over the full option list, not an already pruned one
        keep = [base.get(field)] if base.get(field) in values else []
        spread = [values[0], values[-1], values[len(values) // 2], *values[1:-1]]
        for v in spread:
            if len(keep) >= cap:
                break
            if v not in keep:
                keep.append(v)
        domains[field] = keep
    return domains


def supplier_standard(case, led):
    """Its standard terms for valuation: stated at the opening, then the standard section, plan gaps."""
    b = case["buyer"]
    std = {**{k: v for k, v in (led.get("stated_open") or {}).items() if k != "unit_price"}, **(led.get("std") or {})}
    std.setdefault("payment_days", b["reference_payment_days"])
    if "incoterm" not in std:
        std["incoterm"] = case.get("fixed_terms", {}).get("incoterm") or "EXW"
    return std


def should_cost_row(parts_dossier, sid):
    """The should-cost estimate of this supplier's own plant, else a generic one (no supplier), else None.
    Another supplier's plant estimate says nothing about this one's costs."""
    rows = [
        sc
        for part in (parts_dossier or {}).values()
        for sc in part.get("should_cost", [])
        if sc.get("unit_cost") and sc.get("price_unit") in (None, 1)
    ]
    for pick in ([r for r in rows if r.get("supplier_id") == sid], [r for r in rows if not r.get("supplier_id")]):
        if pick:
            return min(pick, key=lambda r: r["unit_cost"])
    return None


def supplier_model(case, led, tags, dossier_sup, parts_dossier):
    """Our estimate of the supplier for `supplier_value` / the relationship term."""
    model = {
        "standard": supplier_standard(case, led),
        "interest_rate": priors.rate_for(tags),
        "usual_rate": 0.07,
        "ref_price": led.get("price") or 0.0,
    }
    b = case["buyer"]
    if b.get("category_goal") in RELATIONSHIP_GOALS:
        row = should_cost_row(parts_dossier, led.get("supplier_id"))
        # Generic plant estimates are a prior, not a supplier's revealed cost floor.
        full = row["unit_cost"] if row and row.get("supplier_id") == led.get("supplier_id") else None
        own_plant = full is not None
        if full is None and led.get("price"):
            opening = next((p for p in led.get("prices", []) if p), led["price"])
            full = opening * (1 - ((b.get("sustainable_margin_pct") or 8) + 2) / 100)
        if led.get("breakdown_total"):
            full = led["breakdown_total"]
        if full:
            model["full_cost"] = full
            model["cost_uncertainty_pct"] = (row or {}).get("confidence_pct", 15)
            model["cost_source"] = row.get("id") if own_plant else "opening-price prior"
    return model


def _value(case, terms, model):
    try:
        return supplier_value(case, terms, {**model, "extra": model.get("extra", 0.0) - effort(terms, model)})
    except Exception:
        return None


def solve_price(case, levers, model, target):
    """Unit price (2 decimals) that makes the package worth `target` to the supplier."""
    v0 = _value(case, {**levers, "unit_price": 0.0}, model)
    v1 = _value(case, {**levers, "unit_price": 1.0}, model)
    if v0 is None or v1 is None or v1 - v0 <= 1e-9:
        return None
    price = (target - v0) / (v1 - v0)
    return round(price, 2) if price > 0 else None


def cost(case, terms, std, model):
    try:
        sup = None
        if case["buyer"].get("category_goal") in RELATIONSHIP_GOALS and model.get("full_cost"):
            sup = model
        c = value(case, terms, std, sup)["cost"]
        return c if math.isfinite(c) else None
    except Exception:
        return None


def anchor_price(case, led, tags, dossier, drop):
    """First ask: the standing price minus `drop`, not below this supplier's should-cost, and never above
    what we pay today when it asks for an increase."""
    standing = led["price"]
    b = case["buyer"]
    factor = 1.0
    for t in tags:
        factor *= {
            "full_order_book": 0.5,
            "not_strategic": 0.7,
            "price_frozen": 0.5,
            "spare_capacity": 1.3,
            "weak_costing": 1.2,
            "cash_short": 0.8,
        }.get(t, 1.0)
    target = standing * (1 - min(0.35, drop * factor))
    row = should_cost_row(dossier.get("parts"), led.get("supplier_id"))
    if row and row.get("supplier_id") == led.get("supplier_id"):
        lower = row["unit_cost"] * (1 - (row.get("confidence_pct") or 15) / 100)
        # Even an own-plant estimate cannot contradict the supplier's observed offer.
        target = max(target, min(lower, standing * (1 - drop)))
    current = b.get("current_unit_price")
    if current and case.get("type") in ("price_increase", "renewal", "raw_material") and current < standing:
        target = min(target, current)
    return round(min(target, standing), 2)


def schedule(k, horizon):
    """Share of the way from our aspiration to its offer after k of our messages (slow early)."""
    if horizon <= 1:
        return 1.0
    return min(1.0, (k / (horizon - 1)) ** 2)


def build_menu(case, led, model, std, v_asp, v_stand, levels, must_beat):
    """Candidates [{mid, level, terms, c, saving, price, changes}] for the given {level: share} map."""
    domains = lever_domains(case, std)
    if domains is None or v_asp is None or v_stand is None:
        return []
    base = model["standard"]
    domains = _prune(domains, base)
    names = list(domains)
    combos = [dict(zip(names, values, strict=True)) for values in itertools.product(*domains.values())] or [{}]
    menu, seen = [], set()
    for level, share in levels.items():
        target = v_asp + (v_stand - v_asp) * share
        found = []
        for levers in combos:
            price = solve_price(case, levers, model, target)
            if price is None:
                continue
            terms = {**levers, "unit_price": price}
            terms = {f: terms[f] for f in case["negotiable"]}
            if not must_haves_ok(case, terms, std):
                continue
            c = cost(case, terms, std, model)
            if c is None or c >= must_beat - 0.5:
                continue
            changes = sum(levers.get(k) != base.get(k) for k in levers)
            found.append((c, changes, terms))
        found.sort(key=lambda x: (x[0], x[1]))  # ties: stay close to the supplier's own terms
        # Keep each lever's alternatives represented before filling with cheap near-duplicates.
        # Supplier security (indexation/duration) is deliberately outside supplier_value's cash formula.
        diverse, represented = [], set()
        for candidate in found:
            terms = candidate[2]
            features = {(f, str(terms.get(f))) for f in names}
            if not diverse or features - represented:
                diverse.append(candidate)
                represented |= features
        ordered = diverse + [x for x in found if x not in diverse]
        picked = 0
        for c, _, terms in ordered:
            key = tuple(sorted((k, str(v)) for k, v in terms.items()))
            profile = tuple(sorted((k, str(v)) for k, v in terms.items() if k != "unit_price"))
            same_level = [m for m in menu if m["level"] == level]
            if key in seen or profile in {m["profile"] for m in same_level}:
                continue
            seen.add(key)
            menu.append(
                {
                    "level": level,
                    "terms": terms,
                    "c": round(c, 2),
                    "saving": round(must_beat - c, 2),
                    "price": terms.get("unit_price"),
                    "changes": {k: v for k, v in terms.items() if k != "unit_price" and base.get(k) != v},
                    "profile": profile,
                }
            )
            picked += 1
            if picked >= PER_LEVEL:
                break
    for i, m in enumerate(menu, 1):
        m["mid"] = f"M{i}"
        m.pop("profile", None)
    return menu


def describe(case, terms):
    """One human line per sheet, written by code (figures never come from the model)."""
    parts = [f"unit price EUR {terms['unit_price']:.2f}"] if terms.get("unit_price") is not None else []
    labels = {
        "payment_days": lambda v: f"payment {v} days net",
        "lead_time_days": lambda v: f"lead time {v} days",
        "volume_per_year": lambda v: f"{v} pieces a year",
        "contract_months": lambda v: "single order" if v == 0 else f"contract {v} months",
        "effective_date": lambda v: f"valid from {v}",
        "incoterm": lambda v: f"Incoterm {v}",
        "tooling_eur": lambda v: f"tooling EUR {v:,.0f}",
        "ppm_commitment": lambda v: f"quality commitment {v} ppm",
        "chargeback_eur_per_complaint": lambda v: f"chargeback EUR {v} per complaint",
        "index_clause": lambda v: (
            "no index clause"
            if not v
            else f"index clause on {v.get('series')} ({round(100 * v.get('material_share', 0))}% material)"
        ),
    }
    for field in case["negotiable"]:
        if field != "unit_price" and field in terms:
            fmt = labels.get(field, lambda v, f=field: f"{f.replace('_', ' ')} {v}")
            try:
                parts.append(fmt(terms[field]))
            except Exception:
                parts.append(f"{field} {terms[field]}")
    return ", ".join(parts)
"""Observer: one ledger per supplier thread - what it offers, how it moved, how our claims landed."""

import math

from arena_kit.docs import quote_terms, standard_terms
from arena_kit.harness.validation import acceptable
from arena_kit.harness.valuation import ranked_offers, value
from arena_kit.play import ENDED, latest, moves_left, standing

TEXT_CHARS = 1200
ATTACH_CHARS = 1500


def _quote_sections(events):
    """Sections of the first readable quote PDF in the thread (the opening offer)."""
    for msg in events:
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote") and att.get("text"):
                try:
                    return quote_terms(att["text"])
                except Exception:
                    return {}
    return {}


def build(case, threads, models=None):
    out = {}
    for sid, events in threads.items():
        led = {"supplier_id": sid}
        try:
            last = latest(events)
        except StopIteration:
            continue
        offer_id, terms = standing(events)
        model = (models or {}).get(sid)
        ranked = ranked_offers(case, events, model)
        eligible = [s for s in ranked if s["beats_alternative"]]
        if eligible or ranked:
            best = (eligible or ranked)[0]
            offer_id, terms = best["term_sheet_id"], best["terms"]
        led["offers"] = ranked
        led["model"] = model
        led.update(offer_id=offer_id, terms=terms, price=terms.get("unit_price"), status=last.get("status"))
        led["ended"] = last.get("status") in ENDED
        led["std"] = standard_terms(events)
        led["stated_open"] = _quote_sections(events).get("stated", {})
        try:
            valuation = value(case, terms, led["std"], model) if terms else {}
            c = valuation.get("cost", math.inf)
            led.update(
                known_cost=valuation.get("known_cost"), relationship_estimate=valuation.get("relationship_estimate")
            )
        except Exception:
            c = math.inf
        led["c"] = c if math.isfinite(c) else None
        supplier_msgs = [m for m in events if m.get("from") != "buyer"]
        buyer_msgs = [m for m in events if m.get("from") == "buyer"]
        led["prices"] = [(m.get("term_sheets") or [{}])[0].get("terms", {}).get("unit_price") for m in supplier_msgs]
        led["statuses"] = [m.get("status") for m in supplier_msgs]
        led["rounds"] = len(buyer_msgs)
        led["moves_left"] = moves_left(case, events)
        led["our_sheets"] = [[s.get("terms", {}) for s in m.get("term_sheets") or []] for m in buyer_msgs]
        led["missing_fields"] = last.get("missing_fields") or []
        led["claim_results"] = [r.get("result") for r in last.get("claim_results") or []]
        led["claims_total"] = {}
        for m in supplier_msgs:
            for r in m.get("claim_results") or []:
                led["claims_total"][r.get("result")] = led["claims_total"].get(r.get("result"), 0) + 1
        led["from"] = last.get("from")
        led["body"] = (last.get("body") or "")[:TEXT_CHARS]
        led["message_id"] = last.get("message_id")
        led["signals"] = last.get("signals") or {}
        prices = [p for p in led["prices"] if p]
        led["move_pct"] = round((prices[-2] - prices[-1]) / prices[-2] * 100, 2) if len(prices) >= 2 else None
        led["total_move_pct"] = round((prices[0] - prices[-1]) / prices[0] * 100, 2) if len(prices) >= 2 else 0.0
        first_final = next((i for i, s in enumerate(led["statuses"]) if s == "final_offer"), None)
        # supplier message i answers buyer message i-1 (message 0 is the opening quote)
        # only messages with term sheets push; a holding note without sheets does not
        led["pushes_after_final"] = (
            0 if first_final is None else sum(bool(m.get("term_sheets")) for m in buyer_msgs[first_final:])
        )
        led["attachments"] = [
            {"name": a.get("name"), "text": (a.get("text") or "")[:ATTACH_CHARS]}
            for a in last.get("attachments") or []
            if a.get("text") and not a.get("name", "").startswith("quote")
        ]
        led["breakdown"] = any(
            "breakdown" in (a.get("name") or "").lower() for m in supplier_msgs for a in m.get("attachments") or []
        )
        try:
            led["acceptable"] = bool(eligible) and not led["ended"] and acceptable(case, events, offer_id)
        except Exception:
            led["acceptable"] = False
        out[sid] = led
    return out


def digest(led):
    """Compact view for the prompt."""
    return {
        "status": led.get("status"),
        "from": led.get("from"),
        "standing_terms": led.get("terms"),
        "standing_cost_eur": led.get("c"),
        "known_cost_eur": led.get("known_cost"),
        "relationship_estimate_eur": led.get("relationship_estimate"),
        "supplier_cost_assumption": led.get("model"),
        "current_offers": led.get("offers"),
        "price_path": led.get("prices"),
        "status_path": led.get("statuses"),
        "our_messages": led.get("rounds"),
        "moves_left": led.get("moves_left"),
        "last_move_pct": led.get("move_pct"),
        "claims_last": led.get("claim_results"),
        "claims_total": led.get("claims_total"),
        "missing_fields": led.get("missing_fields"),
        "standard_terms": led.get("std"),
        "signals": led.get("signals"),
        "latest_email": led.get("body"),
        "attachments": led.get("attachments"),
    }
"""Decision clock: how much of the engine's budget is left and which mode fits (see the plan)."""

import math
import time

RETURN_MARGIN = 2.0  # validate + encode + pipe after we return
WAVE_GUARD = 90  # the engine closes 90 s before a wave's cap


class Budget:
    def __init__(self, observation, params, now=None):
        self.t0 = time.monotonic() if now is None else now
        ready = observation.get("ready_suppliers") or []
        seconds = observation.get("seconds_left") or {}
        thread_left = min((seconds.get(s, 60) for s in ready), default=60)
        wave = observation.get("wave_seconds_left")
        self.wave_left = wave
        self.total = min(
            params["decision_seconds"],
            thread_left - 5,
            (wave - WAVE_GUARD) if wave is not None else math.inf,
        )
        self.deadline = self.t0 + self.total - RETURN_MARGIN
        self.call = params["model_timeout"] + 1.0

    def remaining(self):
        return self.deadline - time.monotonic()

    def mode(self, llm_ok, refresh_due, two_call_ok):
        """reflex | det | merged | two"""
        if self.total <= 4:
            return "reflex"
        if not llm_ok:
            return "det"
        r = self.remaining()
        if two_call_ok and refresh_due and r >= 2 * self.call + 1 and self.call <= 14:
            return "two"
        if r >= self.call + 1:
            return "merged"
        return "det"

    def can_call(self):
        return self.remaining() >= self.call + 0.5

    def last_round(self, max_latency):
        """Wave pre-close: no time for another reply before the engine's guard."""
        if self.wave_left is None:
            return False
        return self.wave_left - WAVE_GUARD < max(max_latency, 30) + 25

    def horizon(self, sent, moves_left, latencies):
        available = moves_left
        if self.wave_left is not None:
            round_seconds = max(latencies, default=60) + max(1, self.total)
            available = min(available, max(1, int((self.wave_left - WAVE_GUARD) / round_seconds)))
        return max(2, sent + available)

