FAVOURABLE_NEWS = {"free_capacity", "short_time_work"}
MAX_PER_MESSAGE = 3


def ids_in(text):
    return [m.rstrip(".,;)") for m in ID_RE.findall(text or "")]


PER_SUPPLIER = ("quote:", "offer:")  # a rival's quote counts once per supplier, every other ID once per case


